{
  "name": "蠕动泵",
  "name_en": "Peristaltic Pump",
  "manufacturer": "",
  "description": "这是一种实验室蠕动泵，通过滚轮挤压软管实现连续、低脉动的液体输送。它常用于培养基、缓冲液、试剂或废液的定量输送与循环，在微流控、细胞培养、灌流和一般流体处理实验中常见。",
  "description_en": "This is a laboratory peristaltic pump that moves liquid by compressing flexible tubing with rotating rollers, enabling continuous and relatively low-pulsation flow. It is commonly used for metered transfer or circulation of media, buffers, reagents, and waste in microfluidics, cell culture, perfusion, and general fluid-handling experiments.",
  "tag_hints": [
    "peristaltic pump",
    "liquid handling",
    "flow control",
    "tubing pump",
    "perfusion",
    "microfluidics",
    "remote pump control"
  ],
  "actions": [
    {
      "action_name": "auto-getIdentification",
      "description": "读取泵的设备标识信息。",
      "description_en": "Read the pump's identification information."
    },
    {
      "action_name": "auto-enableRemoteControl",
      "description": "启用或关闭泵的远程控制模式。",
      "description_en": "Enable or disable the pump's remote control mode."
    },
    {
      "action_name": "auto-readDisplay",
      "description": "读取泵前面板显示内容。",
      "description_en": "Read the pump's front-panel display content."
    },
    {
      "action_name": "auto-getStatus",
      "description": "读取泵的当前状态。",
      "description_en": "Read the pump's current status."
    },
    {
      "action_name": "auto-close",
      "description": "结束与泵的当前通信会话。",
      "description_en": "Close the current communication session with the pump."
    },
    {
      "action_name": "auto-setFlowDirection",
      "description": "设置泵的流动方向。",
      "description_en": "Set the pump's flow direction."
    },
    {
      "action_name": "auto-setSpeed",
      "description": "设置泵的转速。",
      "description_en": "Set the pump's rotation speed."
    },
    {
      "action_name": "auto-startFlow",
      "description": "按指定速度和方向启动泵送。",
      "description_en": "Start pumping at the specified speed and direction."
    },
    {
      "action_name": "auto-stopFlow",
      "description": "停止泵送。",
      "description_en": "Stop pumping."
    },
    {
      "action_name": "auto-sendImmediate",
      "description": "向指定泵单元发送立即执行的命令。",
      "description_en": "Send a command for immediate execution to the selected pump unit."
    },
    {
      "action_name": "auto-sendBuffered",
      "description": "向指定泵单元发送缓冲命令。",
      "description_en": "Send a buffered command to the selected pump unit."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与泵的通信连接。",
      "description_en": "Disconnect communication with the pump."
    },
    {
      "action_name": "auto-selectUnit",
      "description": "选择要控制的泵单元。",
      "description_en": "Select the pump unit to control."
    },
    {
      "action_name": "auto-sendAndAcknowledge",
      "description": "向泵发送命令并等待确认响应。",
      "description_en": "Send a command to the pump and wait for an acknowledgment."
    },
    {
      "action_name": "auto-sendString",
      "description": "向泵发送原始命令字符串。",
      "description_en": "Send a raw command string to the pump."
    },
    {
      "action_name": "auto-getResponse",
      "description": "读取泵返回的响应信息。",
      "description_en": "Read the response returned by the pump."
    }
  ]
}

